/// What the behavior operations of fixture-pool-api run on: a pool of
/// fixture-pool-db, its database, which `Implementations::new` takes.
#[derive(Clone)]
pub struct Behaviors {
    pool: Pool,
}

impl Behaviors {
    /// The behavior operations' runner on `pool`, a pool of fixture-pool-db.
    pub fn new(pool: Pool) -> Self {
        Self { pool }
    }
}

/// The core with the behaviors superschematic-rules-behaviors registers,
/// built once per process: a `Core` is `Send` and `Sync`, so one serves
/// every request.
fn core() -> &'static Core {
    static CORE: OnceLock<Core> = OnceLock::new();
    CORE.get_or_init(superschematic_rules_behaviors::core)
}

/// RULES_LAYOUT, read once per process.
///
/// # Panics
///
/// When the document does not read: the build wrote it, so that is a
/// defect of the build.
fn layout() -> &'static Layout {
    static LAYOUT: OnceLock<Layout> = OnceLock::new();
    LAYOUT.get_or_init(|| match Layout::from_json(RULES_LAYOUT) {
        Ok(layout) => layout,
        Err(err) => panic!("the behaviors' layout, RULES_LAYOUT, does not read: {err}"),
    })
}

/// The caller the core runs an operation as (D103): the route's principal
/// with the permissions it holds, each once; else a calling service
/// standing in for an end user, which holds none (D37); else no one.
fn caller(ctx: &RequestContext) -> Caller {
    if let Some(principal) = &ctx.principal {
        let mut permissions: Vec<&str> = Vec::new();
        for permission in &principal.permissions {
            if !permissions.contains(&permission.as_str()) {
                permissions.push(permission);
            }
        }
        return Caller::new(principal.subject.clone(), permissions);
    }
    if let Some(service) = &ctx.service_caller {
        return Caller::standing_in(service.deployable.clone());
    }
    Caller::new("", Vec::<String>::new())
}

/// Runs `operation` of the use `use_id` on the row of `type_name` whose key
/// is `key`, with `params`, in a transaction of the pool, as the request's
/// caller, and returns its result once the transaction commits. The key
/// goes to the core in its wire form, its JSON string. A refusal of the
/// core or the adapter rolls the transaction back and is the problem of its
/// status, code, message and details; a refusal of status 500 or of no
/// error status, a failure of the database, the pool's included, and a
/// result that does not read are logged and answered as the server's
/// internal error, as the Go and TypeScript servers answer them.
pub(crate) async fn run_operation<K, P, R>(
    behaviors: &Behaviors,
    ctx: &RequestContext,
    type_name: &str,
    key: &K,
    use_id: &str,
    operation: &str,
    params: &P,
) -> Result<R, ApiError>
where
    K: Serialize + ?Sized,
    P: Serialize + ?Sized,
    R: DeserializeOwned,
{
    let key = match serde_json::to_value(key).map_err(internal)? {
        Value::String(key) => key,
        other => other.to_string(),
    };
    let params = serde_json::to_value(params).map_err(internal)?;
    let mut client = behaviors.pool.get().await.map_err(internal)?;
    let tx = client.transaction().await.map_err(internal)?;
    let host = Host::new(core(), layout());
    let ran = postgres::run_operation(
        &host,
        &*tx,
        type_name,
        &key,
        use_id,
        operation,
        params,
        caller(ctx),
    )
    .await;
    match ran {
        Ok(result) => {
            tx.commit().await.map_err(internal)?;
            serde_json::from_value(result).map_err(internal)
        }
        // Dropping the transaction rolls it back.
        Err(Error::Refused(refusal)) if is_problem(refusal.status) => Err(problem(*refusal)),
        Err(err) => Err(internal(err)),
    }
}

/// Runs `operation` of the use `use_id` on the table of `type_name` as a
/// whole (D104), a command without a row, with `params`, in a transaction of
/// the pool, as the request's caller, and returns its result once the
/// transaction commits: the core writes each row it reaches through a call
/// on that row, each held to its version, and a read-only one writes
/// nothing. Its refusals and failures are answered as `run_operation`'s.
pub(crate) async fn run_table_operation<P, R>(
    behaviors: &Behaviors,
    ctx: &RequestContext,
    type_name: &str,
    use_id: &str,
    operation: &str,
    params: &P,
) -> Result<R, ApiError>
where
    P: Serialize + ?Sized,
    R: DeserializeOwned,
{
    let params = serde_json::to_value(params).map_err(internal)?;
    let mut client = behaviors.pool.get().await.map_err(internal)?;
    let tx = client.transaction().await.map_err(internal)?;
    let host = Host::new(core(), layout());
    let ran = postgres::run_table_operation(
        &host,
        &*tx,
        type_name,
        use_id,
        operation,
        params,
        caller(ctx),
        &ExecuteOptions::default(),
    )
    .await;
    match ran {
        Ok(result) => {
            tx.commit().await.map_err(internal)?;
            serde_json::from_value(result).map_err(internal)
        }
        // Dropping the transaction rolls it back.
        Err(Error::Refused(refusal)) if is_problem(refusal.status) => Err(problem(*refusal)),
        Err(err) => Err(internal(err)),
    }
}

/// Whether a refusal of `status` is answered as its problem: an error
/// status, 400 to 599, other than 500, which is the server's own.
fn is_problem(status: u16) -> bool {
    (400..=599).contains(&status) && status != 500
}

/// The problem of a refusal: its status, code, message and details.
fn problem(refusal: Refusal) -> ApiError {
    let Refusal {
        code,
        status,
        message,
        details,
        ..
    } = refusal;
    let status = StatusCode::from_u16(status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let error = ApiError::new(status, code.as_str(), message);
    match details {
        Some(details) => error.with_details(Value::Object(*details)),
        None => error,
    }
}

/// Logs `err` and answers the server's internal error, with none of its
/// text.
fn internal(err: impl std::fmt::Display) -> ApiError {
    tracing::error!(error = %err, "behavior operation failed");
    ApiError::internal("An unexpected error occurred")
}

/// What an event handler of the API's Workers runs in (D104): the
/// transaction of fixture-pool-db its event's message is spent in, which
/// commits with what the handler writes once it returns `Ok`, and the caller
/// of the behavior worker that claimed it, as which `operation` runs a
/// behavior operation in that transaction.
pub struct EventRun<'a> {
    tx: &'a tokio_postgres::Transaction<'a>,
    caller: Caller,
}

impl EventRun<'_> {
    /// The transaction, for the handler's own statements, which commit with
    /// the event's completion.
    pub fn client(&self) -> &tokio_postgres::Transaction<'_> {
        self.tx
    }

    /// The caller the worker's commands run as.
    pub fn caller(&self) -> &Caller {
        &self.caller
    }

    /// Runs `operation` of the use `use_id` on the row of `type_name` whose
    /// key is `key`, with `params`, in the transaction, as the worker, and
    /// returns its result: the adapter's `run_operation` with the module's
    /// core and layout. The key goes to the core in its wire form, its JSON
    /// string. A refusal leaves the transaction going on, nothing of the
    /// operation written.
    pub async fn operation<K, P, R>(
        &self,
        type_name: &str,
        key: &K,
        use_id: &str,
        operation: &str,
        params: &P,
    ) -> Result<R, Error>
    where
        K: Serialize + ?Sized,
        P: Serialize + ?Sized,
        R: DeserializeOwned,
    {
        let key = match serde_json::to_value(key).map_err(unconverted)? {
            Value::String(key) => key,
            other => other.to_string(),
        };
        let params = serde_json::to_value(params).map_err(unconverted)?;
        let host = Host::new(core(), layout());
        let result = postgres::run_operation(
            &host,
            self.tx,
            type_name,
            &key,
            use_id,
            operation,
            params,
            self.caller.clone(),
        )
        .await?;
        serde_json::from_value(result).map_err(unconverted)
    }
}

/// A key, params or a result of an event handler's operation that does not
/// convert to or from JSON, refused as the adapter refuses a defect.
fn unconverted(err: serde_json::Error) -> Error {
    Error::from(Refusal::internal(format!(
        "rules: a behavior operation's value does not convert: {err}"
    )))
}

/// The caller AccountRechecks's commands run as (D103): the worker, not a user,
/// holding the permissions its @behaviorWorker grants.
fn account_rechecks_caller() -> Caller {
    Caller::new("fixture-pool-api/AccountRechecks", ["accounts.pool"])
}

/// The deadline queue of the behavior worker AccountRechecks (D103),
/// fixture-pool-db's AccountDeadline, on `pool`, a pool of fixture-pool-db:
/// a queue whose handler, `run_account_rechecks_deadline`, completes each message
/// itself, which `worker::run_worker` runs.
pub fn account_rechecks_deadlines(
    pool: &Pool,
) -> Result<SelfCompleting<PostgresQueue<AccountDeadline>>, BoxError> {
    let definition = QueueDefinition::parse(ACCOUNT_DEADLINE_QUEUE)?;
    let queue = PostgresQueue::new(pool.clone(), definition);
    Ok(SelfCompleting::new(queue))
}

/// Runs a claimed deadline of Account through the behaviors' core on a
/// transaction of the pool, as the worker, at the later of now and the time
/// it was armed to fall due at, its message's completion in the same commit
/// (D103). A deadline armed or cleared since the claim, or of a row or a use
/// that is gone, runs nothing, and a fire a guard vetoes is released, due
/// again in a minute, each of which it logs; a refusal or a failure of the
/// database rolls the transaction back and fails the message, which the
/// queue retries after its backoff.
pub async fn run_account_rechecks_deadline(
    pool: &Pool,
    claimed: Claimed<AccountDeadline>,
) -> Result<(), BoxError> {
    let deadline = deadline_of(&claimed.message)?;
    let claim = Claim {
        id: claimed.id.clone(),
        token: claimed.token.clone(),
    };
    let mut client = pool.get().await?;
    let tx = client.transaction().await?;
    let host = Host::new(core(), layout());
    let run = postgres::run_deadline(
        &host,
        &*tx,
        "Account",
        &deadline,
        account_rechecks_caller(),
        Some(&claim),
    )
    .await?;
    tx.commit().await?;
    if !matches!(run, DeadlineRun::Ran(_)) {
        tracing::info!(
            message = claimed.id.as_str(),
            why = run.why(),
            "deadline ran nothing"
        );
    }
    Ok(())
}

/// The event queue of the behavior worker AccountRechecks (D104),
/// fixture-pool-db's AccountEvent, on `pool`, a pool of fixture-pool-db:
/// a queue whose handler, `run_account_rechecks_event`, completes each message
/// itself, which `worker::run_worker` runs.
pub fn account_rechecks_events(
    pool: &Pool,
) -> Result<SelfCompleting<PostgresQueue<AccountEvent>>, BoxError> {
    let definition = QueueDefinition::parse(ACCOUNT_EVENT_QUEUE)?;
    let queue = PostgresQueue::new(pool.clone(), definition);
    Ok(SelfCompleting::new(queue))
}

/// Spends a claimed event of Account in a transaction of the pool and
/// hands it to the Workers method of its use and kind, as the worker, then
/// commits both (D104): the method's writes and the message's completion
/// commit together or not at all. A claim lost runs nothing, which it logs;
/// the method's error, an event no method takes and a failure of the
/// database roll the transaction back and fail the message, which the queue
/// retries after its backoff until its retries are spent.
pub async fn run_account_rechecks_event(
    pool: &Pool,
    workers: &dyn crate::Workers,
    claimed: Claimed<AccountEvent>,
) -> Result<(), BoxError> {
    let claim = Claim {
        id: claimed.id.clone(),
        token: claimed.token.clone(),
    };
    let mut client = pool.get().await?;
    let tx = client.transaction().await?;
    let host = Host::new(core(), layout());
    let spent = postgres::spend_event(&host, &*tx, "Account", Some(&claim)).await?;
    if !spent.ran() {
        tracing::info!(
            message = claimed.id.as_str(),
            why = spent.why(),
            "event ran nothing"
        );
        return Ok(());
    }
    let run = EventRun {
        tx: &tx,
        caller: account_rechecks_caller(),
    };
    account_rechecks_event(workers, &run, &claimed.message).await?;
    tx.commit().await?;
    Ok(())
}

/// Hands an event of Account's event queue to the Workers method of its use
/// and kind (D104), the event read as the method's type through serde_json.
/// An event no method takes fails its message, which is dead after its
/// retries, for an operator.
async fn account_rechecks_event(
    workers: &dyn crate::Workers,
    run: &EventRun<'_>,
    message: &AccountEvent,
) -> Result<(), BoxError> {
    let event = event_of(message)?;
    match (event.use_id.as_str(), event.kind.as_str()) {
        ("Pool", "recheck") => {
            let typed = serde_json::from_value(event.event)?;
            workers.account_rechecks_pool_recheck(typed, run).await
        }
        (use_id, kind) => Err(format!(
            "behavior worker AccountRechecks: no Workers method takes event {kind} of {use_id} on Account {} (D104)",
            event.key
        )
        .into()),
    }
}

/// The deadline a message of a deadline queue holds (D103): its row's key
/// in its wire form, the use, the deadline's name, the time it was armed to
/// fall due at and its payload, null when it has none.
fn deadline_of<M: Serialize>(message: &M) -> Result<Deadline, BoxError> {
    let Value::Object(mut fields) = serde_json::to_value(message)? else {
        return Err("a deadline's message is no object".into());
    };
    let mut text = |name: &str| -> Result<String, BoxError> {
        match fields.remove(name) {
            Some(Value::String(text)) => Ok(text),
            Some(other) if !other.is_null() => Ok(other.to_string()),
            _ => Err(format!("a deadline's message has no {name}").into()),
        }
    };
    let (key, use_id, name) = (text("rowKey")?, text("useId")?, text("name")?);
    let at = fields
        .get("at")
        .and_then(Value::as_i64)
        .ok_or("a deadline's message has no at")?;
    Ok(Deadline {
        key,
        use_id,
        name,
        at,
        payload: fields.remove("payload").unwrap_or(Value::Null),
    })
}

/// An event a message of an event queue holds (D104): the use that emitted
/// it, its kind, its row's key in its wire form, and the event a Workers
/// method takes, `{ key, at, payload }`: the row's key, the time of the
/// command that emitted it in epoch milliseconds, and what it says.
struct EventMessage {
    use_id: String,
    kind: String,
    key: String,
    event: Value,
}

fn event_of<M: Serialize>(message: &M) -> Result<EventMessage, BoxError> {
    let Value::Object(mut fields) = serde_json::to_value(message)? else {
        return Err("an event's message is no object".into());
    };
    let mut text = |name: &str| -> Result<String, BoxError> {
        match fields.remove(name) {
            Some(Value::String(text)) => Ok(text),
            Some(other) if !other.is_null() => Ok(other.to_string()),
            _ => Err(format!("an event's message has no {name}").into()),
        }
    };
    let (use_id, kind) = (text("useId")?, text("kind")?);
    let row_key = fields
        .remove("rowKey")
        .filter(|key| !key.is_null())
        .ok_or("an event's message has no rowKey")?;
    let at = fields
        .remove("at")
        .filter(Value::is_number)
        .ok_or("an event's message has no at")?;
    let key = match &row_key {
        Value::String(key) => key.clone(),
        other => other.to_string(),
    };
    let mut event = Map::new();
    event.insert("key".to_owned(), row_key);
    event.insert("at".to_owned(), at);
    event.insert(
        "payload".to_owned(),
        fields.remove("payload").unwrap_or(Value::Null),
    );
    Ok(EventMessage {
        use_id,
        kind,
        key,
        event: Value::Object(event),
    })
}
